-- ============================================================
-- RESUMEN VERIFICACIÓN
-- ============================================================
SELECT 'pedidos por mes' AS dato,
       to_char(fecha_creacion AT TIME ZONE 'UTC', 'YYYY-MM') AS mes,
       count(*) AS n,
       sum(total) AS total
  FROM pedidos
 WHERE vendedor_id = :'norangel' AND notas = 'SEED-2026'
 GROUP BY 2 ORDER BY 2;

SELECT 'prospectos creados por mes' AS dato, to_char(fecha_creacion, 'YYYY-MM') AS mes, count(*) AS n
  FROM clientes
 WHERE vendedor_id = :'norangel' AND estado = 'prospecto' AND empresa LIKE 'TEST-%'
 GROUP BY 2 ORDER BY 2;

SELECT 'actividades completadas Ago' AS dato, count(*) AS n
  FROM actividades
 WHERE vendedor_id = :'norangel' AND titulo LIKE 'TEST-%' AND completado
   AND fecha >= '2026-08-01' AND fecha < '2026-09-01';

SELECT 'oportunidades por etapa' AS dato, etapa, count(*) AS n
  FROM oportunidades
 WHERE vendedor_id = :'norangel' AND titulo LIKE 'TEST-%'
 GROUP BY etapa ORDER BY etapa;
